link","shed","location1"],["loose","nut1"],["loose","nut2"],["loose","nut3"],["useable","spanner1"],["useable","spanner2"],["useable","spanner3"]],"objects":[["bob","man"],["gate","location"],["location1","location"],["location2","location"],["location3","location"],["location4","location"],["nut1","nut"],["nut2","nut"],["nut3","nut"],["shed","location"],["spanner1","spanner"],["spanner2","spanner"],["spanner3","spanner"]],"task_id":"spannerlearning/seed0/problem0"},{"family":"planning","goal":[["tightened","nut1"],["tightened","nut2"],["tightened","nut3"]],"init":[["at","bob","shed"],["at","nut1","gate"],["at","nut2","gate"],["at","nut3","gate"],["at","spanner1","location3"],["at","spanner2","location4"],["at","spanner3","location4"],["link","location1","location2"],["link","location2","location3"],["link","location3","location4"],["link","location4","gate"],["link","shed","location1"],["loose","nut1"],["loose","nut2"],["loose","nut3"],["useable","spanner1"],["useable","spanner2"],["useable","spanner3"]],"objects":[["bob","man"],["gate","location"],["location1","location"],["location2","location"],["location3","location"],["location4","location"],["nut1","nut"],["nut2","nut"],["nut3","nut"],["shed","location"],["spanner1","spanner"],["spanner2","spanner"],["spanner3","spanner"]],"task_id":"spannerlearning/seed0/problem1"}],"registration":{"auxiliary":{"hypothesis":"If the historical operator_syntax rejection stems solely from leading/trailing ASCII whitespace outside or just inside the parenthesized payload, the normalized plan should pass the same host syntax check, reach VAL, and validate under public STRIPS replay, yielding supported for both instances.","plANNING":"problem0: unknown; problem1: unknown. Historical observations report error_kind=operator_syntax with plan_length 11 and executed_actions 0 on both public instances, which is consistent with a malformed emitted plan string (e.g. stray leading/trailing whitespace or misplaced parentheses) rather than a